dashboard.definition:
{
  "title": "1 · Medical Device IP Drift",
  "description": "Detect when a medical device with a reserved IP silently receives a DHCP lease.",
  "inputs": {},
  "defaults": {},
  "visualizations": {
    "bg_001": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "bg_002": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#16A3B0",
        "strokeColor": "#16A3B0",
        "strokeWidth": 1,
        "rx": 3
      }
    },
    "md_003": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "USE CASE 1 OF 9  ·  SPITAL AARWALD  ·  SAMPLE DATA",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "md_004": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "# Medical Device IP Drift",
        "fontColor": "#E6EDF3"
      }
    },
    "md_005": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Reserved IPs silently replaced by DHCP leases — detected in minutes, with the switch port.",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 15
      }
    },
    "bg_006": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#11161D",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 8
      }
    },
    "md_007": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "WHAT WE HEARD",
        "fontColor": "#6E7681",
        "fontSize": "custom",
        "customFontSize": 11
      }
    },
    "md_008": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "*“Ein Röntgengerät ist letzte Woche ausgestiegen, weil die IP-Adresse aus unerklärlichen Gründen auf DHCP umgestellt wurde.”*",
        "fontColor": "#9AA4B2",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_009": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_010": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "imaging · lab · monitoring · infusion",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13
      },
      "dataSources": {
        "primary": "ds_011"
      },
      "title": "Devices with reserved IP"
    },
    "bg_012": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_013": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "> majorValue | rangeValue(majorColorConfig)",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "underLabel": "rolling 7-day count",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_014"
      },
      "title": "Unexpected IP changes (7 days)",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ],
        "majorColorConfig": [
          {
            "to": 1,
            "value": "#E6EDF3"
          },
          {
            "from": 1,
            "value": "#FAB219"
          }
        ]
      }
    },
    "bg_015": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_016": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "> majorValue | rangeValue(majorColorConfig)",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "absolute",
        "sparklineDisplay": "off",
        "underLabel": "need action",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13,
        "trendColor": "> trendValue | rangeValue(trendColorConfig)"
      },
      "dataSources": {
        "primary": "ds_017"
      },
      "title": "Reserved devices on DHCP now",
      "context": {
        "trendColorConfig": [
          {
            "to": -0.0001,
            "value": "#0CA30C"
          },
          {
            "from": -0.0001,
            "to": 0.0001,
            "value": "#9AA4B2"
          },
          {
            "from": 0.0001,
            "value": "#D03B3B"
          }
        ],
        "majorColorConfig": [
          {
            "to": 1,
            "value": "#0CA30C"
          },
          {
            "from": 1,
            "value": "#D03B3B"
          }
        ]
      }
    },
    "bg_018": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_019": {
      "type": "splunk.singlevalue",
      "options": {
        "backgroundColor": "#161B22",
        "majorColor": "#E6EDF3",
        "numberPrecision": 0,
        "shouldUseThousandSeparators": true,
        "majorFontSize": 42,
        "trendFontSize": 15,
        "trendDisplay": "off",
        "sparklineDisplay": "below",
        "showSparklineAreaGraph": true,
        "sparklineStrokeColor": "#16A3B0",
        "sparklineAreaColor": "#16A3B0",
        "unit": " min",
        "unitPosition": "after",
        "underLabel": "was ~3.5 h before Splunk",
        "underLabelColor": "#9AA4B2",
        "underLabelFontSize": 13
      },
      "dataSources": {
        "primary": "ds_020"
      },
      "title": "Mean time to detect"
    },
    "bg_021": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_022": {
      "type": "splunk.column",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "bottom",
        "xAxisTitleVisibility": "hide",
        "seriesColors": [
          "#3987E5",
          "#199E70",
          "#9085E9",
          "#D95926"
        ],
        "stackMode": "stacked",
        "yAxisTitleVisibility": "hide"
      },
      "dataSources": {
        "primary": "ds_023"
      },
      "title": "DHCP events per hour — medical device VLANs (24h)"
    },
    "bg_024": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_025": {
      "type": "splunk.pie",
      "options": {
        "backgroundColor": "#161B22",
        "showDonutHole": true,
        "labelDisplay": "valuesAndPercentage",
        "legendDisplay": "off",
        "seriesColors": [
          "#3987E5",
          "#D95926",
          "#199E70",
          "#C98500",
          "#D55181",
          "#008300",
          "#9085E9",
          "#E66767"
        ]
      },
      "dataSources": {
        "primary": "ds_026"
      },
      "title": "Unexpected IP changes by device class (30 days)"
    },
    "bg_027": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_028": {
      "type": "splunk.table",
      "options": {
        "backgroundColor": "#161B22",
        "headerVisibility": "fixed",
        "fontSize": "small",
        "columnFormat": {
          "When": {
            "width": 90
          },
          "Device": {
            "width": 105
          },
          "Location": {
            "width": 150
          },
          "Reserved IP": {
            "width": 110
          },
          "Leased IP": {
            "width": 110
          },
          "Switch port": {
            "width": 185
          },
          "Status": {
            "width": 90,
            "rowBackgroundColors": "> table | seriesByName(\"Status\") | matchValue(c0Bg)",
            "rowColors": "> table | seriesByName(\"Status\") | matchValue(c0Fg)"
          }
        }
      },
      "dataSources": {
        "primary": "ds_029"
      },
      "title": "Reserved devices that received a DHCP lease (7 days)",
      "context": {
        "c0Bg": [
          {
            "match": "Open",
            "value": "#3F1D20"
          },
          {
            "match": "Resolved",
            "value": "#12301B"
          }
        ],
        "c0Fg": [
          {
            "match": "Open",
            "value": "#FF8A80"
          },
          {
            "match": "Resolved",
            "value": "#56D364"
          }
        ]
      }
    },
    "bg_030": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "viz_031": {
      "type": "splunk.area",
      "options": {
        "backgroundColor": "#161B22",
        "legendDisplay": "off",
        "xAxisTitleVisibility": "hide",
        "nullValueDisplay": "connect",
        "lineWidth": 2,
        "seriesColors": [
          "#D95926"
        ],
        "yAxisTitleVisibility": "hide"
      },
      "dataSources": {
        "primary": "ds_032"
      },
      "title": "XR-RAD-03 — failed image sends to PACS (6h)"
    },
    "bg_033": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#161B22",
        "strokeColor": "#262C36",
        "strokeWidth": 1,
        "rx": 12
      }
    },
    "md_034": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "DATA SOURCES NEEDED IN SPLUNK",
        "fontColor": "#16A3B0",
        "fontSize": "custom",
        "customFontSize": 12
      }
    },
    "bg_035": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_036": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "DHCP server logs",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_037": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_038": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Switch & router syslog",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_039": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_040": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "Cisco ISE",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_041": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
