    },
    "md_042": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "PACS / DICOM gateway logs",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    },
    "bg_043": {
      "type": "splunk.rectangle",
      "options": {
        "fillColor": "#1C2530",
        "strokeColor": "#2D3A48",
        "strokeWidth": 1,
        "rx": 17
      }
    },
    "md_044": {
      "type": "splunk.markdown",
      "options": {
        "markdown": "CMDB / asset inventory",
        "fontColor": "#E6EDF3",
        "fontSize": "custom",
        "customFontSize": 13
      }
    }
  },
  "dataSources": {
    "ds_011": {
      "type": "ds.search",
      "name": "ds_011",
      "options": {
        "query": "| makeresults format=csv data=\"ago,devices\n13,1230\n12,1237\n11,1237\n10,1243\n9,1245\n8,1252\n7,1256\n6,1260\n5,1264\n4,1266\n3,1269\n2,1276\n1,1277\n0,1284\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time devices",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_014": {
      "type": "ds.search",
      "name": "ds_014",
      "options": {
        "query": "| makeresults format=csv data=\"ago,changes\n13,3\n12,4\n11,3\n10,3\n9,7\n8,6\n7,6\n6,7\n5,6\n4,8\n3,9\n2,5\n1,4\n0,7\"\n| eval _time=relative_time(now(), \"@d\") - ago*86400\n| sort 0 _time\n| table _time changes",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_017": {
      "type": "ds.search",
      "name": "ds_017",
      "options": {
        "query": "| makeresults format=csv data=\"ago,devices\n1,2\n0,1\"\n| eval _time=relative_time(now(), \"@h\") - ago*3600\n| sort 0 _time\n| table _time devices",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_020": {
      "type": "ds.search",
      "name": "ds_020",
      "options": {
        "query": "| makeresults format=csv data=\"ago,minutes\n11,215\n10,190\n9,240\n8,205\n7,180\n6,12\n5,8\n4,6\n3,5\n2,4\n1,5\n0,4\"\n| eval _time=relative_time(now(), \"@d\") - ago*604800\n| sort 0 _time\n| table _time minutes",
        "queryParameters": {
          "earliest": "-15m",
          "latest": "now"
        }
      }
    },
    "ds_023": {
      "type": "ds.search",
      "name": "ds_023",
